# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">MUSTAFA 1881-1920 TARİHE ATILAN İMZA: BİYOGRAFİ VE ANI UNSURLARI</text>\n  <rect x="35" y="50" width="300" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="185" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Biyografi (Yaşam Öyküsü) Özellikleri</text>\n  <text x="50" y="105" font-size="11.5" fill="#334155">• Tanınmış bir kişinin hayatı kronolojik</text>\n  <text x="62" y="123" font-size="11" fill="#475569">sırayla ve belgelere dayanılarak anlatılır.</text>\n  <text x="50" y="150" font-size="11.5" fill="#334155">• Üçüncü kişi ağzıyla (o / yapmıştır, gitmiştir)</text>\n  <text x="62" y="168" font-size="11" fill="#475569">nesnel ve bilgilendirici bir dil kullanılır.</text>\n  <text x="50" y="195" font-size="11.5" fill="#334155">• Kişinin kendi hayatını yazmasına ise</text>\n  <text x="62" y="213" font-size="11" font-weight="bold" fill="#1e40af">otobiyografi (öz yaşam öyküsü) denir.</text>\n  <rect x="365" y="50" width="300" height="185" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="515" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">1881-1920 Tarihsel Dönüm Noktaları</text>\n  <text x="380" y="105" font-size="11.5" fill="#334155">• 1881 Selanik: Doğumu ve eğitim hayatı</text>\n  <text x="380" y="130" font-size="11.5" fill="#334155">• 1911 Trablusgarp &amp; 1915 Çanakkale Zaferi</text>\n  <text x="380" y="155" font-size="11.5" fill="#334155">• 19 Mayıs 1919 Samsun\'a Çıkış, Amasya,</text>\n  <text x="392" y="173" font-size="11" fill="#475569">Erzurum ve Sivas Kongreleri</text>\n  <text x="380" y="198" font-size="11.5" fill="#334155">• 23 Nisan 1920 TBMM\'nin Açılışı</text>\n  <text x="515" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#991b1b">Kararlılık, Vatanseverlik ve İleri Görüşlülük</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">METİNDE ÖRTÜLÜ ANLAM, GEÇİŞ İFADELERİ VE SÖZ VARLIĞI</text>\n  <rect x="35" y="50" width="300" height="185" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="185" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Örtülü Anlam (Çıkarım Yapma)</text>\n  <text x="50" y="105" font-size="11.5" fill="#334155">• Cümlede doğrudan söylenmeyen ancak</text>\n  <text x="62" y="123" font-size="11" fill="#475569">yardımcı sözcüklerden (de, bile, yine, artık,</text>\n  <text x="62" y="140" font-size="11" fill="#475569">ilk kez, en) çıkarılan gizli anlamdır.</text>\n  <text x="50" y="168" font-size="11.5" font-weight="bold" fill="#166534">Örnek: &quot;Mustafa bu sınavı da kazandı.&quot;</text>\n  <text x="50" y="190" font-size="11" fill="#334155">→ Örtülü Anlam: Daha önce başka sınavları</text>\n  <text x="62" y="208" font-size="11" fill="#334155">da kazandığı anlaşılır.</text>\n  <rect x="365" y="50" width="300" height="185" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="515" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Düşünceyi Yönlendiren İfadeler</text>\n  <text x="380" y="105" font-size="11.5" fill="#334155">• Zıtlık / Geçiş: ama, fakat, lakin, ancak,</text>\n  <text x="392" y="123" font-size="11" fill="#475569">oysaki, ne var ki, buna rağmen</text>\n  <text x="380" y="150" font-size="11.5" fill="#334155">• Destekleyici / Açıklayıcı: özellikle, hatta,</text>\n  <text x="392" y="168" font-size="11" fill="#475569">üstelik, başka bir deyişle, açıkçası</text>\n  <text x="380" y="195" font-size="11.5" fill="#334155">• Özetleyici: kısacası, özetle, sonuç olarak</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">FİİLLERDE KİP (ZAMAN / ANLAM) KAYMASI</text>\n  <rect x="30" y="55" width="310" height="175" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="185" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Anlam (Zaman) Kayması Nedir?</text>\n  <text x="45" y="110" font-size="11.5" fill="#334155">• Fiilin aldığı kip eki ile cümlenin kastettiği</text>\n  <text x="57" y="128" font-size="11" fill="#475569">zaman veya anlamın farklı olmasıdır.</text>\n  <text x="45" y="155" font-size="11.5" fill="#334155">• Bir anlatım bozukluğu değildir; tarihsel</text>\n  <text x="57" y="173" font-size="11" fill="#475569">metinlerde anlatıma canlılık katar.</text>\n  <text x="185" y="208" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">Zarf tümleci gerçek zamanı ele verir!</text>\n  <rect x="360" y="55" width="310" height="175" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="515" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Örnek Çözümlemeler</text>\n  <text x="375" y="108" font-size="11" font-weight="bold" fill="#166534">1) &quot;Mustafa Kemal 1919\'da Samsun\'a çıkar.&quot;</text>\n  <text x="385" y="126" font-size="11" fill="#334155">Biçim: Geniş zaman (-r) → Anlam: Geçmiş (-dı)</text>\n  <text x="375" y="152" font-size="11" font-weight="bold" fill="#166534">2) &quot;Yarın Ankara\'ya gidiyorum.&quot;</text>\n  <text x="385" y="170" font-size="11" fill="#334155">Biçim: Şimdiki (-yor) → Anlam: Gelecek (-ecek)</text>\n  <text x="375" y="196" font-size="11" font-weight="bold" fill="#166534">3) &quot;Her sabah erken kalkıyor.&quot;</text>\n  <text x="385" y="214" font-size="11" fill="#334155">Biçim: Şimdiki (-yor) → Anlam: Geniş zaman (-r)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
